create table if not exists public.bms_xero_review_decisions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,receipt_id uuid not null,decision text not null check(decision in ('not_job_related')),reason text not null check(length(trim(reason)) between 4 and 500),actor_user_id uuid not null,created_at timestamptz not null default now(),unique(tenant_id,receipt_id));create index if not exists bms_xero_review_decisions_tenant_idx on public.bms_xero_review_decisions(tenant_id,created_at desc);alter table public.bms_xero_review_decisions enable row level security;revoke all on public.bms_xero_review_decisions from anon,authenticated;create or replace function public.bms_mark_xero_not_job_related(p_tenant uuid,p_receipt uuid,p_actor uuid,p_reason text) returns boolean language plpgsql security definer set search_path=public as $$begin if length(trim(coalesce(p_reason,''))) not between 4 and 500 then raise exception 'A review reason is required';end if; if not exists(select 1 from public.business_software_accounting_unmatched_receipts where id=p_receipt and tenant_id=p_tenant and provider='xero' and status='needs_review') then raise exception 'Xero review item unavailable';end if; insert into public.bms_xero_review_decisions(tenant_id,receipt_id,decision,reason,actor_user_id) values(p_tenant,p_receipt,'not_job_related',trim(p_reason),p_actor) on conflict(tenant_id,receipt_id) do nothing; update public.business_software_accounting_unmatched_receipts set status='ignored' where id=p_receipt and tenant_id=p_tenant and provider='xero' and status='needs_review';return true;end $$;revoke all on function public.bms_mark_xero_not_job_related(uuid,uuid,uuid,text) from public,anon,authenticated;grant execute on function public.bms_mark_xero_not_job_related(uuid,uuid,uuid,text) to service_role,postgres;
